            this.nnTest15 = this.$$('.nn_test_15');
            this.boundTrain15 = this.$$('.bound_train_15');
            this.boundTest15 = this.$$('.bound_test_15');
            this.invAccTrain = this.$$('.inv_acc_train');
            this.invAccTest = this.$$('.inv_acc_test');
